// The plugin's commands (each gets an `allow-<command>` permission in permissions/autogenerated) and its Android
// library (android/), which tauri-build adds to the generated Android project.
const COMMANDS: &[&str] = &["listar", "abrir", "leer", "cerrar"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).android_path("android").build();
}
